spawn.example:
const { Light } = kcds.world;
const { Vector3 } = kcds.math;

const lantern = Light.spawn(new Vector3(2293.2, 2026.0, 106.5), {
  color: { x: 1, y: 0.55, z: 0.2 },
  intensity: 2,
  radius: 8,
});

// A torch's glow on a player's right hand.
Light.spawn(new Vector3(0, 0, 0.3), { entity: player, joint: 'RightHand', radius: 6 });

spawn.exampleCs:
var lantern = Light.Spawn(new Vector3(2293.2, 2026.0, 106.5), new { color = new { x = 1, y = 0.55, z = 0.2 }, intensity = 2, radius = 8 });

// A torch's glow on a player's right hand.
Light.Spawn(new Vector3(0, 0, 0.3), new { entity = player, joint = "RightHand", radius = 6 });

valid.example:
// client
const { Light } = kcds.world;
const { LocalPlayer } = kcds.players;

let lamp = Light.spawn(LocalPlayer.position, { radius: 4 });
if (!lamp.valid) {
  lamp = Light.spawn(LocalPlayer.position, { radius: 4 });
}

